import{_ as s,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const d=JSON.parse('{"title":"AniME: Adaptive Multi-Agent Planning for Long Animation Generation","description":"","frontmatter":{"title":"AniME: Adaptive Multi-Agent Planning for Long Animation Generation","arxiv":"2508.18781","date":"2025-08-26","authors":"Lisai Zhang, Baohan Xu, Siqian Yang, Mingyu Yin, Jing Liu, Chao Xu, Siqi Wang, Yidi Wu, Yuxin Hong, Zihao Zhang, Yanzhang Liang, Yudong Jiang","categories":"cs.AI, cs.MM","topics":"智能体视频生成, 长动画生成, MCP 工具选择","outline":[2,2]},"headers":[],"relativePath":"papers/2508.18781.md","filePath":"papers/2508.18781.md","lastUpdated":null}'),r={name:"papers/2508.18781.md"};function i(o,a,p,l,g,c){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="anime-adaptive-multi-agent-planning-for-long-animation-generation" tabindex="-1">AniME: Adaptive Multi-Agent Planning for Long Animation Generation <a class="header-anchor" href="#anime-adaptive-multi-agent-planning-for-long-animation-generation" aria-label="Permalink to &quot;AniME: Adaptive Multi-Agent Planning for Long Animation Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2508.18781" target="_blank" rel="noreferrer">2508.18781</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-08-26（本页依据 arXiv HTML <strong>v3</strong>（2025-10-10）全文撰写；arXiv comments 标注 <strong>2 pages, Technical Report</strong>，正文仅两页，附录 A 是主要内容）</td></tr><tr><td><strong>作者</strong></td><td>Lisai Zhang, Baohan Xu, Siqian Yang, Mingyu Yin, Jing Liu, Chao Xu, Siqi Wang, Yidi Wu, Yuxin Hong, Zihao Zhang, Yanzhang Liang, Yudong Jiang（Bilibili Inc.）</td></tr><tr><td><strong>分类</strong></td><td>cs.AI, cs.MM</td></tr><tr><td><strong>一句话</strong></td><td>用一个导演 agent 维护工作流图与带版本控制的共享资产库，并在 MCP 协议里显式标注每个生成工具的领域专长与局限，让下游 agent 按镜头类型自己挑控制条件模型。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">关于本文的证据强度</p><p>这是一篇 <strong>2 页的技术报告</strong>。全文<strong>没有任何定量实验、没有基线对比、没有用户研究、也没有消融实验</strong>。本页 §7 如实记录这一点，不代填任何数字。下文的所有描述都是对论文所述<strong>设计</strong>的复述，而非对其<strong>效果</strong>的验证。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>长动画生成与长视频生成不完全是同一个问题。动画有相对固定的工业流程（角色设计、场景设计、分镜、原动画、配音、剪辑），有强烈的角色身份约束（一个角色的脸在整部片里必须是同一张），并且不同类型的镜头需要完全不同的生成手段——空镜、对白特写、多角色群戏，各自适合的控制方式不一样。</p><p>AniME 面对的问题是：怎么把一个完整故事自动拆解并调度到这一整套异构工具上，且在几十上百个镜头的尺度上不让角色身份漂移。论文来自 Bilibili，工业背景明显，关注点更偏系统架构而非算法创新。</p><p>它值得读的地方有两处。其一是 <strong>Asset Memory Bank 的单写者语义</strong>——一个把「谁有权修改角色身份」这件事写死在架构里的设计。其二是<strong>把工具的局限性显式写进 MCP 协议</strong>，让 agent 选工具时能读到「这个工具不擅长什么」。这两点都是从工程实践里长出来的，不是论文式的巧思。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>需要先说清楚一件事：由于本文只有两页，它对前人工作的讨论极为简略，下面的对照有一部分是基于论文所述设计动机的合理推断，而非论文的显式论述。</p><p><strong>已有的多 agent 视频/动画框架</strong>（DreamFactory、MovieAgent、AniMaker、MAViS 这一系）都建立了「LLM 规划 + 现成生成模型执行」的范式。它们的资产管理通常是隐式的：角色描述作为文本在 agent 之间传递，或者用一张参考图贯穿全程。这种做法在几十个镜头的尺度上会累积漂移，因为没有任何机制规定「谁可以改这个角色的定义」——任何一个 agent 在改写 prompt 时都可能悄悄改变角色的特征描述。</p><p><strong>工具调用</strong>这一侧，主流做法是把可用工具列成一个清单交给 LLM 选。清单通常只写工具能做什么，不写它做不好什么。于是 agent 会在不合适的场合选错工具，且没有信息可据以避免。</p><p><strong>同组前作</strong>：论文引用了 AniSora（arXiv 2412.10255, Jiang et al. 2024），其作者与本文作者有重叠（Yudong Jiang、Baohan Xu、Siqian Yang），可视为同一团队在动画生成方向上的延续工作。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从工业动画制作的真实约束出发：制作是一张有向依赖图，角色设计必须先于分镜，分镜必须先于原动画。任何一环返工，下游全部作废。真实剧组的应对方式不是重做整条流水线，而是<strong>局部返工</strong>——只重画出问题的那一张。</p><p>把这个约束搬进 agent 系统，就得到两个设计决定。第一，需要一个显式的工作流图而不是线性 pipeline，这样才能知道某个节点失败会波及哪些下游节点。第二，需要一个共享的资产存储，让局部重做的结果能被下游正确读到，而不需要重跑上游。</p><p>接下来的问题是：既然多个 agent 都要读写这个存储，怎么防止角色身份被写乱。答案是从并发编程里借来的<strong>单写者语义</strong>——只有 Character Designer 有权更新 identity 相关字段，其他 agent 只读。再加上版本控制与回滚，就得到了一个可审计的资产库。</p><p>最后一个问题是工具选择。作者的观察是，分镜这一个任务就至少有三种技术路线，各有各的失效场合。与其硬编码规则，不如把每个工具的适用与不适用场合写成 MCP 里的元数据，让 agent 自己读。这是本文真正想主张的那个 claim。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>长动画生成的失败不是单点画错，而是错误沿着依赖链扩散。所以系统的核心不该是更强的生成器，而是一个能定位错误、只重做受影响节点的依赖图，加上一个规定了谁能改什么的资产库。工具选择同理：与其让 agent 猜哪个模型合适，不如把每个模型不擅长什么直接告诉它。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>Director Agent</strong> 是整个系统的调度中枢，做四件事：把故事 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 按语义相似度、情绪状态转移与时间标记（对白断点、动作节拍）切成 scene 与 shot；确定视觉风格向量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与听觉风格 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">a</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>；用 CoT 生成任务表 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span>；维护一张工作流图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mclose">)</span></span></span></span>，节点是生产任务、边是依赖关系（例如 character design → storyboard → animation）。执行按拓扑序进行，<strong>低质量输出只触发局部重做，不重跑整条 pipeline</strong>。</p><p><strong>七个专用 agent</strong>（论文 Table 1 给出了各自的 Inputs / Outputs / Tools）：Script &amp; Storyboard、Character Designer、Scene Designer、Animator、Audio Production、Video Editor、Quality Evaluator。</p><p><strong>Asset Memory Bank</strong>（Table 2）是一组可查询、带版本、带 embedding 的表，字段如下：<code>shot(id, description)</code>、<code>scene(id, prompt, view_3d)</code>、<code>character(id, prompt, demo_voice, voice_prompt, 3d_view)</code>、<code>style(id, visual_style, acoustic_style)</code>、<code>storyboard(id, prompt, image_path)</code>、<code>video(id, prompt, video_path, shot_id, music_id)</code>、<code>music(id, character_id, prompt, music_path)</code>。防漂移机制是 canonical 字段的<strong>单写者语义</strong>：只有 Character Designer 能更新 identity vector，其他 agent 只读；所有条目带版本，支持回滚与分支。Character Designer 另外用 CLIP 打分对齐已存的 embedding 来强制身份一致，并做失败检测拒掉漂移的输出。</p><p><strong>MCP 工具选择</strong>是本文的核心主张：在 MCP 协议里显式标注每个工具的领域专长与局限。论文 Table 3 给出分镜工具的三选一及其适用条件——Text-to-Image（简单、适合无角色的 establishing shot；但布局难控、跨镜头一致性差）、Reference Image Generation（能保角色一致、适合对白镜头；但生成不了空场）、Layout-Guided Generation（空间控制强、适合多角色密集画面；但复杂度与布局设计开销高）。</p><p><strong>Agent 间通信</strong>用结构化 JSON。request 含 <code>id</code>、<code>type</code>、<code>task{prompt, requirement}</code>、<code>assets{style, identity}</code>、<code>meta{version, producer}</code>；response 含 <code>status</code>、<code>outputs{keyframes, camera_plan{angles, transitions}}</code>、<code>meta</code>。消息支持版本化与 provenance 追溯。</p><p><strong>论文给的例子</strong>：场景 <code>scene_YX01</code> 有三个 shot，Director 分别为它们选了 <code>reference_image_generation</code>、带 bbox 的 <code>layout_guided_generation</code>、以及用于特写的 <code>layout_guided_generation</code>。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>这一节必须如实说明：本文是一篇 2 页技术报告，全文没有提供任何定量实验、任何基线比较、任何用户研究、任何消融实验。</strong> 论文只给出三张描述性表格——Table 1 列出七个 agent 的输入输出与所用工具，Table 2 列出 Asset Memory Bank 的表结构与字段，Table 3 列出三种分镜工具的专长与局限——以及一个 <code>scene_YX01</code> 的定性调度示例。</p><p>因此，关于 AniME 的以下问题目前都<strong>没有答案</strong>：单写者语义相比自由读写能把角色身份漂移降低多少；MCP 里的工具局限性标注相比不标注能提升多少工具选择正确率；局部重做相比全流程重跑省下多少算力；Quality Evaluator 触发重做的频率是多少；成片质量与同期的 MAViS、AniMaker 相比如何。</p><p>这是一个必须保留的阴性结果。论文本身没有宣称做过这些实验，问题不在于作者隐瞒，而在于<strong>读者不应把这篇报告当作已验证的方法</strong>。它提供的是一份可实现的架构说明，其有效性有待独立验证。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：AniME 是 Bilibili 提出的长动画生成多 agent 架构，由一个 Director Agent 维护工作流图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mclose">)</span></span></span></span> 并按拓扑序调度七个专用 agent。它最实在的设计是 Asset Memory Bank 的单写者语义——只有 Character Designer 能写 identity 字段，配合版本控制与回滚，把角色一致性做成架构约束而非事后检查。第二个主张是在 MCP 协议里显式标注工具的局限性，让 agent 按镜头类型自选分镜方案（T2I 用于空镜、reference image 用于对白、layout-guided 用于群戏）。低质量输出只触发局部重做而非全流程重跑。<strong>但全文是 2 页技术报告，没有任何定量实验支撑上述任何一条。</strong></p><p><strong>3 句话版</strong>：把动画制作的依赖关系显式建成图，把角色身份的写权限收归单一 agent，把工具的失效场合写进协议元数据。这三条都是有价值的工程判断。它们目前没有任何实验证据。</p><p><strong>1 句话版</strong>：一份读起来很合理、但完全未经验证的长动画生成系统架构说明。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p><strong>假设：Quality Evaluator 判得准。</strong> 整套架构的收敛完全押在它身上——Director 的局部重做机制由它触发，工作流图的拓扑推进由它放行，版本回滚由它决定。论文提到 Quality Evaluator 依据几项自动指标工作：text-to-video similarity、identity verification、AV sync、以及 VLM 的叙事评估。</p><p>问题在于，论文<strong>没有对这些指标做任何校准</strong>，也没有报告触发重做的频率。这两个缺口叠加起来会产生两种同样糟糕的失败，且从外部无法区分：如果评估器过于宽松，坏结果会被放行并沿依赖链扩散到下游，局部重做机制形同虚设；如果过于严格，系统会在某些节点上反复重做直到耗尽预算，而论文没有描述任何终止条件。</p><p>identity verification 这一项尤其值得怀疑。它大概率是某种嵌入相似度加阈值，而动漫角色的判别与真人脸完全不同——同一角色在不同景别、不同光照、不同作画状态下的嵌入距离，可能大于两个同画风不同角色之间的距离。同期的 AniMaker（arXiv 2506.10540）明确指出 MTCNN 这类真人脸检测器在动漫脸上不可用，为此专门在 Anime Face Dataset 上训了新的一致性判别器。AniME 没有交代它的 identity verification 用的是什么模型、在什么数据上验证过。</p><p>一个未经校准的评估器驱动的自动重做机制，其表现无法从架构图上判断，只能靠实验。这正是本文缺的东西。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，只验证最值钱的那个设计点，不需要实现整个七 agent 系统：</p><ol><li>实现一个最小的 Asset Memory Bank：<code>character</code> 表带 identity vector 字段、带版本号。做两个版本——<strong>A 组</strong>执行单写者语义（只有 Character Designer 能写 identity 字段），<strong>B 组</strong>允许任何 agent 在改写 prompt 时更新它。</li><li>用同一个故事（10 到 15 个镜头，含 2 到 3 个角色）在两组配置下各跑 5 次，生成分镜图序列。</li><li><strong>先做校准，再做评测</strong>：人工标注约 300 对动漫角色图片（同角色不同姿态 / 不同景别 / 不同光照为正样本，同画风不同角色为负样本），测出所用相似度模型的 ROC 与最优阈值。<strong>如果 AUC 低于 0.8，就不能用它来判身份漂移</strong>，需要换模型或改用人工评判。</li><li>用校准后的阈值统计两组的身份漂移率（相对第一次出现时的 canonical 向量），并报告一个<strong>平凡基线</strong>：全程使用同一张固定参考图、不做任何 agent 协商的漂移率是多少。</li></ol><p>判据：只有当 A 组显著优于 B 组<strong>且</strong>显著优于固定参考图这个平凡基线时，单写者语义才算被验证有价值。若固定参考图就已经足够，那么整套版本化资产库的复杂度就没有回报。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释：MCP 里的工具局限性标注可以被一条硬编码规则完全复现。</strong> 这是对本文核心主张最直接的攻击。论文 Table 3 的三种分镜工具，其适用条件写下来其实非常简单：镜头里没有角色就用 Text-to-Image，有一到两个角色且以对白为主就用 Reference Image Generation，角色数多或画面密集就用 Layout-Guided Generation。这三条完全可以写成一个 if-else。</p><p>设计对照实验：构造 200 个镜头描述，覆盖三类场合各若干。<strong>A 组</strong>用论文的方式——把工具的专长与局限写进 MCP 元数据，让 LLM agent 自主选择；<strong>B 组</strong>用上述三行 if-else 规则；<strong>C 组</strong>作为平凡基线，全部无条件使用 Layout-Guided Generation（能力最强、开销最大的那个）。用人工标注的「最合适工具」作为 ground truth，比较三组的选择正确率与总开销。</p><p>如果 A 组不显著优于 B 组，那么「让 agent 读工具说明自己选」这个 claim 就退化成了一个 if-else 的昂贵包装——它没有带来新能力，只是把规则从代码挪到了 prompt 里。如果连 C 组的成片质量都与 A 组相当，那么工具选择这件事本身就不重要，论文的核心贡献落空。</p><p><strong>这个反例之所以有力，是因为论文没有提供任何数据来排除它。</strong> 两页的篇幅里，Table 3 是唯一支撑该主张的材料，而它只是一张人写的适用性描述表，不是实验结果。</p><p><strong>可预测的失败条件</strong>：论文声称 Director 按语义相似度、情绪状态转移与时间标记切分 scene 与 shot。对于叙事结构规整的作品这大概能work，但对于闪回、平行剪辑、梦境嵌套这类<strong>时间线非线性</strong>的故事，「按时间标记切分」会把本应交错的镜头切成错误的顺序，而工作流图的拓扑排序会把这个错误固化下来——因为图的依赖关系是在切分之后建立的，切错了就没有任何下游机制能纠正。构造一个含闪回的短故事作为测试用例，观察切分结果，这是本文架构里最容易暴露的结构性弱点。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动它的局限</strong>：MCP 里的工具能力描述是<strong>人写的静态自然语言</strong>。写它的人凭经验判断某个模型擅长什么，而模型每次更新这份描述就过期一次；更麻烦的是，人写的描述只覆盖已知的失效模式，那些没被注意到的失效模式永远不会进入描述，agent 也就永远学不会避开。</p><p><strong>(b) 可借鉴的相邻领域</strong>：算法选择（algorithm selection）与 meta-learning 里的 performance prediction。把工具能力从「人写的文档」换成「从执行日志里自动学到的能力画像」：每次调用记录（镜头特征，所选工具，Quality Evaluator 打分，是否触发重做），拟合一个条件成功率模型 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">p</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mopen">(</span><span class="mord text"><span class="mord">success</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">shot features</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">tool</span></span><span class="mclose">)</span></span></span></span>，agent 按预测成功率与开销做选择。这样能力画像随模型版本自动更新，且能发现人没写进文档的失效模式（例如「这个工具在夜景多角色场景下成功率骤降」）。</p><p><strong>(c) 第一个实验</strong>：分三步，且顺序不能颠倒。<strong>第一步是校准</strong>——建立能力画像的前提是 Quality Evaluator 的分数可信，所以必须先用人工标注测出它的准确率与偏差方向，这正是本文完全没做的事；若它不可信，学出来的画像只会是它的偏差的镜像。<strong>第二步是平凡基线</strong>——在收集到的日志上，先报告「永远选 Layout-Guided Generation」与「按 Table 3 的 if-else 选」这两个基线的成功率，任何学习方法必须超过它们。<strong>第三步</strong>才是训练与部署能力画像，并在一批新镜头上比较三者。真正有意思的输出不是准确率，而是画像学到的失效模式与 Table 3 人写描述之间的<strong>差集</strong>——那些人没写、模型发现了的条件，才是这个方向真正的价值所在。</p>',56)])])}const h=s(r,[["render",i]]);export{d as __pageData,h as default};
